PRAGMA foreign_keys = ON;
CREATE TABLE users(uid TEXT PRIMARY KEY, public_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL,email TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','ativa','bloqueada')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_seen_at TEXT NOT NULL);
CREATE INDEX users_status ON users(status,name);
CREATE TABLE projects(id TEXT PRIMARY KEY,owner_uid TEXT NOT NULL REFERENCES users(uid),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',start_date TEXT NOT NULL DEFAULT '',end_date TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('Planejamento','Em andamento','Em atenção','Concluído')),budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(budget_cents>=0),archived_at TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX projects_owner ON projects(owner_uid);
CREATE INDEX projects_status ON projects(archived_at,status,end_date);
CREATE TABLE project_members(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,uid TEXT NOT NULL REFERENCES users(uid),role TEXT NOT NULL CHECK(role IN ('gestor','colaborador','leitor')),status TEXT NOT NULL CHECK(status IN ('ativo','revogado')),granted_by TEXT NOT NULL REFERENCES users(uid),granted_at TEXT NOT NULL,revoked_at TEXT,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(project_id,uid));
CREATE INDEX members_uid ON project_members(uid,status,project_id);
CREATE TABLE admin_audit_logs(id TEXT PRIMARY KEY,actor_uid TEXT NOT NULL,action TEXT NOT NULL,target_uid TEXT,project_id TEXT,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX audit_date ON admin_audit_logs(created_at,id);
CREATE TABLE project_charters(id TEXT PRIMARY KEY,project_id TEXT NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE,justification TEXT NOT NULL DEFAULT '',objective TEXT NOT NULL DEFAULT '',sponsor TEXT NOT NULL DEFAULT '',manager TEXT NOT NULL DEFAULT '',scope TEXT NOT NULL DEFAULT '',exclusions TEXT NOT NULL DEFAULT '',deliverables TEXT NOT NULL DEFAULT '',assumptions TEXT NOT NULL DEFAULT '',constraints TEXT NOT NULL DEFAULT '',success_criteria TEXT NOT NULL DEFAULT '',initial_start_date TEXT NOT NULL DEFAULT '',initial_end_date TEXT NOT NULL DEFAULT '',initial_budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(initial_budget_cents>=0),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE project_phases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0 CHECK(position>=0),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE INDEX phases_project ON project_phases(project_id,position);
CREATE TABLE project_tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',phase_id TEXT,responsible TEXT NOT NULL DEFAULT '',start_date TEXT NOT NULL DEFAULT '',end_date TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('Não iniciada','Em andamento','Bloqueada','Concluída','Cancelada')),completed_date TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('atividade','marco')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(phase_id,project_id) REFERENCES project_phases(id,project_id));
CREATE INDEX tasks_project ON project_tasks(project_id,status,end_date);
CREATE TABLE project_risks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,code TEXT NOT NULL,description TEXT NOT NULL,probability TEXT NOT NULL CHECK(probability IN ('Baixa','Média','Alta')),impact TEXT NOT NULL CHECK(impact IN ('Baixa','Média','Alta')),responsible TEXT NOT NULL DEFAULT '',response_plan TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('Aberto','Em tratamento','Encerrado')),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX risks_project ON project_risks(project_id,status);
CREATE TABLE project_costs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,category TEXT NOT NULL,description TEXT NOT NULL,planned_cents INTEGER NOT NULL CHECK(planned_cents>=0),actual_cents INTEGER NOT NULL CHECK(actual_cents>=0),date TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX costs_project ON project_costs(project_id);
CREATE TABLE project_quality_checks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,code TEXT NOT NULL,requirement TEXT NOT NULL,acceptance TEXT NOT NULL DEFAULT '',responsible TEXT NOT NULL DEFAULT '',result TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('Pendente','Aprovado','Reprovado')),evidence_url TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX quality_project ON project_quality_checks(project_id);
CREATE TABLE project_stakeholders(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,organization TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT '',contact TEXT NOT NULL DEFAULT '',interest TEXT NOT NULL CHECK(interest IN ('Baixa','Média','Alta')),influence TEXT NOT NULL CHECK(influence IN ('Baixa','Média','Alta')),notes TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX stakeholders_project ON project_stakeholders(project_id);
CREATE TABLE project_documents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',url TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX documents_project ON project_documents(project_id);
